// The Cleric's-house furniture, decor and story props — each its own PNG,
// extracted from the concept art (tools/extract+segment+select-house-assets.py).
// Referenced by props whose kind is "h_<name>" and drawn whole (drawHouseObj).
export const HOUSE_OBJ = {};                  // name -> { img, ready }
const HOUSE_NAMES = ["apothecary","armchair","bed","bedside","bench","bench_long",
    "book_green","book_red","bookshelf","bottle","cabinet","candelabra","candle",
    "chair","chair_b","chalice","chest","cross","cupboard","curtains","desk",
    "dining_table","flowers","flowers_yellow","font","frame","globe","herbs","icon",
    "journal","letter","low_table","medicine_stand","nightstand","panacea","plant",
    "records","rug","rug_stone","sconce","screen","side_table","washstand","wedding",
    // the cottage's yard — fence, cart and the small authored details outside
    "fence","cart","bush","rock","flowerbush","wildflowers","stone","signpost","bucket",
    // Mirka asleep in her sickbed — one prop, cut from the second-floor plan
    "bed_mirka","fireplace"];

// A flat-coloured copy of an atlas, keeping only its silhouette.
//
// Two uses: white to flash a sprite when it takes a hit, and near-black to draw
// an outline behind one. Both want the same thing — the shape with the detail
// thrown away — so they are the same function with a colour.
function makeMask(img, colour) {
    const c = document.createElement("canvas");
    c.width = img.width; c.height = img.height;
    const g = c.getContext("2d");
    g.drawImage(img, 0, 0);
    g.globalCompositeOperation = "source-in";
    g.fillStyle = colour;
    g.fillRect(0, 0, c.width, c.height);
    return c;
}

/// Where the outline is stamped: the four cardinal neighbours. Diagonals add a
/// corner pixel the eye barely registers and half again as much work.
const RIM = [[-1, 0], [1, 0], [0, -1], [0, 1]];

/// A copy of an atlas with a dark rim baked behind every cell.
///
/// Baked once rather than stamped per frame. Drawing the silhouette four times
/// under each actor at render time was correct and cost forty frames a second —
/// measured: 61 fps without it, 21 with, on the outdoor map with about seventy
/// actors on screen. Here the same work happens once per atlas and every frame
/// afterwards is a single drawImage, exactly as before.
///
/// Each cell is clipped while its rim is drawn, or the outline of one sprite
/// would bleed a pixel into the sprite packed next to it.
///
/// The rim is DILATED ONCE and laid down ONCE. Drawing the four offsets straight
/// onto the result at 0.75 each accumulated: a pixel with the silhouette on two
/// sides came out at 0.94, on four sides at 0.996 — which is to say opaque. The
/// one-pixel gaps in these sprites are exactly the places that have the
/// silhouette on several sides, so they filled in solid: the guard's hand welded
/// to his body, the woodcutter's two legs fused into one stump, the old man's
/// feet swallowed. The art was whole the whole time; the rim was eating it.
///
/// Uniform 0.45 is enough to separate a figure from ground this busy — which is
/// the only thing the rim is for — while leaving a one-pixel gap reading as a
/// gap.
const RIM_ALPHA = 0.45;

function makeOutlined(img, cells) {
    const dark = makeMask(img, "#0b0812");
    // The dilation, at full strength, on its own canvas. Overlapping offsets
    // here cost nothing: opaque over opaque is still opaque.
    const spread = document.createElement("canvas");
    spread.width = img.width; spread.height = img.height;
    const sg = spread.getContext("2d");
    sg.imageSmoothingEnabled = false;

    const c = document.createElement("canvas");
    c.width = img.width; c.height = img.height;
    const g = c.getContext("2d");
    g.imageSmoothingEnabled = false;

    for (const r of cells) {
        sg.save();
        sg.beginPath(); sg.rect(r.x, r.y, r.w, r.h); sg.clip();
        for (const [ox, oy] of RIM)
            sg.drawImage(dark, r.x, r.y, r.w, r.h, r.x + ox, r.y + oy, r.w, r.h);
        sg.restore();
    }

    g.globalAlpha = RIM_ALPHA;
    g.drawImage(spread, 0, 0);
    g.globalAlpha = 1;
    for (const r of cells)
        g.drawImage(img, r.x, r.y, r.w, r.h, r.x, r.y, r.w, r.h);
    return c;
}

/// The cell rectangles of a fixed-grid atlas.
const gridCells = (img, cw, ch) => {
    const out = [];
    for (let y = 0; y + ch <= img.height; y += ch)
        for (let x = 0; x + cw <= img.width; x += cw) out.push({ x, y, w: cw, h: ch });
    return out;
};

/// The chars atlas is packed rather than gridded, so its cells come from the
/// frame table — which arrives by fetch, after the image. Baking waits for both.
function bakeChars() {
    const a = ATLAS.chars;
    if (!a.ready || !charFrames || a.outlined) return;
    a.outlined = makeOutlined(a.img, Object.values(charFrames).flat()
        .map(f => ({ x: f.x, y: f.y, w: f.w, h: f.h })));
}

export function loadAtlases(onFramesReady) {
    for (const a of Object.values(ATLAS)) {
        if (a.img) continue;
        const im = new Image();
        im.onload = () => {
            a.ready = true;
            if ("white" in a) a.white = makeMask(im, "#ffffff");   // only atlases that flash
            // Only the atlases that draw actors carry a silhouette. Terrain and
            // props deliberately do not have one, so no amount of calling
            // drawSprite wrongly can put an outline round a tree.
            if ("dark" in a) a.dark = makeMask(im, "#0b0812");
        };
        im.onerror = () => console.error("sprite atlas failed to load:", a.src);
        im.src = a.src;
        a.img = im;
    }
    for (const n of HOUSE_NAMES) {
        if (HOUSE_OBJ[n]) continue;
        const im = new Image();
        const rec = { img: im, ready: false };
        im.onload = () => { rec.ready = true; };
        im.onerror = () => console.error("house object failed to load:", n);
        im.src = `assets/Outside/house/obj/${n}.png`;
        HOUSE_OBJ[n] = rec;
    }
    if (!outsideFrames)
        fetch("assets/Outside/atlas_outside.json")
            .then(r => r.json())
            .then(j => { outsideFrames = j; onFramesReady?.(); })
            .catch(e => console.error("outside atlas frame table failed:", e));
    if (!charFrames)
        fetch("assets/Outside/atlas_chars.json")
            .then(r => r.json())
            .then(j => { charFrames = j; bakeChars(); })
            .catch(e => console.error("character atlas frame table failed:", e));
}

// Per-entity animation clocks. The engine sends positions, not a "moving" flag,
// so the stride is advanced by distance actually travelled — the walk cycle then
// stays in step at any speed and settles into a slow sway when standing still.
const animState = new Map();
export function animFrame(key, e, count, stride = 7) {
    let a = animState.get(key);
    if (!a) { a = { p: 0, x: e.x, y: e.y }; animState.set(key, a); }
    const d = Math.hypot(e.x - a.x, e.y - a.y);
    a.x = e.x; a.y = e.y;
    a.p += d > 0.03 ? d / stride : 0.04;
    return Math.floor(a.p) % count;
}

// Blits one cell, horizontally centred on cx with the atlas ground line landing
// on footY. Aligning the ground line rather than the cell bottom is what lets a
// pose whose effect hangs below the boots sit on the floor without lifting the
// hero off it.
/// @param outline  True to draw from the outlined copy of the atlas.
///
/// The rim is what makes an actor readable on ground it happens to match. The
/// outdoor tiles are a busy green-brown, and so is the Thief — no adjustment to
/// the floor separates those two, because they are the same colour. A silhouette
/// one pixel out in every direction separates anything from anything.
export function drawSprite(a, col, row, cx, footY, scale, flip, alpha, flash, outline = false) {
    const dw = a.cw * scale, dh = a.ch * scale;
    const top = footY - (a.ground ?? a.ch) * scale;
    ctx.save();
    ctx.imageSmoothingEnabled = false;      // keep the pixel art crisp
    ctx.globalAlpha = alpha;
    ctx.translate(cx, 0);
    if (flip) ctx.scale(-1, 1);

    const src = outline && a.outlined ? a.outlined : a.img;
    ctx.drawImage(src, col * a.cw, row * a.ch, a.cw, a.ch, -dw / 2, top, dw, dh);
    if (flash > 0 && a.white) {
        ctx.globalAlpha = Math.min(0.85, flash * 6) * alpha;
        ctx.drawImage(a.white, col * a.cw, row * a.ch, a.cw, a.ch, -dw / 2, top, dw, dh);
    }
    ctx.restore();
}
